#include <vector>

using namespace std;

class Solution {
public:
    vector<vector<int>> spiralMatrixIII(int R, int C, int r0, int c0) {
        vector<vector<int>> res;
        int steps = 0, len = 1, dir = 0;
        vector<int> dr = {0, 1, 0, -1}, dc = {1, 0, -1, 0};

        while (res.size() < R * C) {
            if (dir == 0 || dir == 2) ++steps;
            for (int i = 0; i < steps; ++i) {
                if (r0 >= 0 && r0 < R && c0 >= 0 && c0 < C) {
                    res.push_back({r0, c0});
                }
                r0 += dr[dir];
                c0 += dc[dir];
            }
            dir = (dir + 1) % 4;
        }
        return res;
    }
};
